'use strict';
const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const root='releases/v404',base='releases/v402',read=(dir,name)=>fs.readFileSync(dir+'/'+name,'utf8');
const hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const manifest=JSON.parse(read(root,'manifest.json')),provenance=JSON.parse(read(root,'provenance.json'));
assert.equal(manifest.release,'v404');assert.equal(manifest.base_release,'v402');assert.equal(manifest.entry,'app.html');
assert.deepEqual([...Object.keys(manifest.files),'manifest.json'].sort(),fs.readdirSync(root).sort(),'all release assets covered');
assert.deepEqual(Object.keys(provenance.protected_base_files).sort(),fs.readdirSync(base).sort(),'all prior assets protected');
for(const[name,expected]of Object.entries(manifest.files))assert.equal(hash(root+'/'+name),expected,'release '+name);
for(const[name,expected]of Object.entries(provenance.protected_base_files))assert.equal(hash(base+'/'+name),expected,'immutable base '+name);
assert.equal(manifest.protected_manifest.path,base+'/manifest.json');assert.equal(hash(manifest.protected_manifest.path),manifest.protected_manifest.sha256);
const allowed=['app.html','lts-v384-startup-1.js','manifest.json','provenance.json'];
assert.deepEqual(fs.readdirSync(root).sort(),fs.readdirSync(base).sort(),'same runtime inventory');
assert.deepEqual(fs.readdirSync(root).filter(name=>hash(root+'/'+name)!==hash(base+'/'+name)).sort(),allowed.sort(),'only FGTS presentation and release identity change');
const fixture=read('.github/fixtures/fgts-dashboard','fixture-runtime.js'),anchor='  function dashboard178(){';
assert.equal(fixture.split(anchor).length,2);const helper=fixture.slice(0,fixture.indexOf(anchor));
const original=read(base,'lts-v384-startup-1.js'),old="   kpi(root,'FGTS',c?.fgts,'Recurso restrito');";
assert.equal(original.split(anchor).length,2);assert.equal(original.split(old).length,2);
const expected=original.replace(anchor,helper+anchor).replace(old,"   const fgtsPosition=dashboardFgtsPosition(state.wealth.status==='ready'?state.wealth.data:null);\n   kpi(root,'FGTS',fgtsPosition.balance,fgtsPosition.note);");
assert.equal(read(root,'lts-v384-startup-1.js'),expected,'only the reviewed documentary FGTS display changes');
assert.equal(read(root,'app.html'),read(base,'app.html').replaceAll('V402','V404').replace('v402-daily-cofrinho-20261102','v404-fgts-documentary-20261104'));
const live=process.env.LTS_MOBILE_RELEASE||'v404';assert.deepEqual(JSON.parse(read('mobile','current.json')),{release:live,entry:'../releases/'+live+'/app.html'});
for(const key of ['candidate_only','original_financial_sources_changed','original_cash_forecasts_changed','private_http_validated','physical_mobile_validated'])assert.equal(provenance[key],false,key);
assert.equal(provenance.isolated_recovered_fgts_reader_validated,true);
assert.equal(provenance.other_rpc_responses_in_private_fgts_test,'fictional repository fixture');
console.log(JSON.stringify({pass:true,release:'v404',assets:fs.readdirSync(root).length,immutable_v402:true,only_fgts_documentary_display_changed:true,stable_mobile_entry:true,financial_source_writes:0}));
